#include <stdio.h>

int main(void) {
    int bowls[5] = {0};
    int n = 0;

    if (scanf("%d", &n) != 1) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    int total = 0;
    for (int i = 0; i < n; i++) {
        total = total + bowls[i];
    }
    printf("一共 %d 条{unit}喵\n", total);
    return 0;
}
